  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-pleasure-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-pleasure/m2_email-f006de02dc78.gif","alt":"Месяц наслаждений","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":135},{"id":"month-pleasure-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше - в направлении здоровья мочеполовой системы и гармоничной второй чакры.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#fc38be;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#fc38be;mso-line-height-rule:exactly\">Открыть урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
